"""Reusable column groups."""

from __future__ import annotations

from datetime import datetime

from sqlalchemy import BigInteger, Identity, func
from sqlalchemy.orm import Mapped, mapped_column

from app.db.types import UtcDateTime


class IdPrimaryKeyMixin:
    """Surrogate ``BIGINT GENERATED BY DEFAULT AS IDENTITY`` primary key."""

    id: Mapped[int] = mapped_column(BigInteger, Identity(), primary_key=True)


class TimestampMixin:
    """Row bookkeeping timestamps, set by the database clock in UTC.

    ``updated_at`` is refreshed automatically for ORM updates. Bulk upserts in the
    repositories set it explicitly, because ``onupdate`` does not apply to them.
    """

    created_at: Mapped[datetime] = mapped_column(
        UtcDateTime, nullable=False, server_default=func.now()
    )
    updated_at: Mapped[datetime] = mapped_column(
        UtcDateTime, nullable=False, server_default=func.now(), onupdate=func.now()
    )
